                                python: `import heapq

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
    def find(self, i):
        if self.parent[i] == i: return i
        self.parent[i] = self.find(self.parent[i])
        return self.parent[i]
    def union(self, i, j):
        root_i, root_j = self.find(i), self.find(j)
        if root_i != root_j:
            self.parent[root_j] = root_i
            return True
        return False

def kruskal_mst(v_count: int, edges: list):
    # edges = [(u, v, weight), ...]
    edges.sort(key=lambda x: x[2])
    dsu = DSU(v_count)
    mst = []
    total_cost = 0
    for u, v, w in edges:
        if dsu.union(u, v):
            mst.append((u, v, w))
            total_cost += w
            if len(mst) == v_count - 1: break
    return total_cost, mst

def prim_mst(v_count: int, adj_list: list):
    visited = [False] * v_count
    pq = [(0, 0, -1)] # (weight, curr_node, parent)
    total_cost = 0
    mst_edges = []
    
    while pq and len(mst_edges) < v_count:
        w, u, p = heapq.heappop(pq)
        if visited[u]: continue
        visited[u] = True
        total_cost += w
        if p != -1: mst_edges.append((p, u, w))
        for v, weight in adj_list[u]:
            if not visited[v]:
                heapq.heappush(pq, (weight, v, u))
    return total_cost, mst_edges`,
                                java: `import java.util.*;

public class MST {
    static class DSU {
        int[] parent;
        DSU(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int i) {
            return parent[i] == i ? i : (parent[i] = find(parent[i]));
        }
        boolean union(int i, int j) {
            int rI = find(i), rJ = find(j);
            if (rI != rJ) { parent[rJ] = rI; return true; }
            return false;
        }
    }

    public static int kruskal(int vCount, int[][] edges) {
        Arrays.sort(edges, (a, b) -> Integer.compare(a[2], b[2]));
        DSU dsu = new DSU(vCount);
        int totalCost = 0, count = 0;
        for (int[] edge : edges) {
            if (dsu.union(edge[0], edge[1])) {
                totalCost += edge[2];
                if (++count == vCount - 1) break;
            }
        }
        return totalCost;
    }`,
